import axios from 'axios';
import store from '../store';
import { loginSuccess, logout } from '../store/slices/authSlice';

const API_URL = 'https://online.susu.ru/microgateway/api';

// Создаем экземпляр axios с базовой конфигурацией
const api = axios.create({
    baseURL: API_URL
});

// Локальная проверка срока действия JWT-токена без сетевых запросов
const isTokenExpired = (token) => {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(
            atob(base64)
                .split('')
                .map((c) => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2))
                .join('')
        );

        const { exp } = JSON.parse(jsonPayload);
        const currentTime = Math.floor(Date.now() / 1000);
        return exp < currentTime;
    } catch (err) {
        console.error('Error checking token expiration in authApi:', err);
        return true;
    }
};

// Функция для проверки валидности токена офлайн: только по exp
const validateToken = async (token) => {
    if (!token) return false;
    return !isTokenExpired(token);
};

// Добавляем перехватчик для добавления токена к каждому запросу
api.interceptors.request.use(
    (config) => {
        const token = localStorage.getItem('authToken');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

// Добавляем перехватчик для обработки ответов
api.interceptors.response.use(
    (response) => response,
    (error) => {
        if (error.response?.status === 401) {
            localStorage.removeItem('authToken');
            localStorage.removeItem('userData');
            store.dispatch(logout());
        }
        return Promise.reject(error);
    }
);

// Функция для проверки и восстановления сессии
const checkAndRestoreSession = async () => {
    const savedToken = localStorage.getItem('authToken');
    const savedUserData = localStorage.getItem('userData');

    if (savedToken && savedUserData) {
        try {
            // Проверяем валидность токена
            const isValid = await validateToken(savedToken);
            
            if (isValid) {
                const userData = JSON.parse(savedUserData);
                // Восстанавливаем сессию: передаем accessToken так же, как при обычном логине
                store.dispatch(loginSuccess({ accessToken: savedToken, ...userData }));
            } else {
                // Если токен невалиден, очищаем данные
                localStorage.removeItem('authToken');
                localStorage.removeItem('userData');
                store.dispatch(logout());
            }
        } catch (error) {
            console.error('Error restoring session:', error);
            localStorage.removeItem('authToken');
            localStorage.removeItem('userData');
            store.dispatch(logout());
        }
    }
};

// Запускаем проверку сессии при загрузке
checkAndRestoreSession();

const authApi = {
    login: async (credentials) => {
        try {
            const formData = new FormData();
            formData.append('login', credentials.login);
            formData.append('password', credentials.password);
            const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
            const length = 32;
            const randomString = Array.from({ length }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join('');
            formData.append('identity', randomString);
            
            const response = await axios.post(`${API_URL}/Auth/Login`, formData, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                },
            });

            // Проверяем наличие токена в ответе
            console.log(response.data);
            if (response.data && response.data.accessToken) {
                const { accessToken, ...userData } = response.data;
                
                // Сохраняем токен и данные пользователя
                localStorage.setItem('authToken', accessToken);
                localStorage.setItem('userData', JSON.stringify(userData));
                
                // Обновляем состояние Redux
                store.dispatch(loginSuccess({ accessToken, ...userData }));
                
                return { success: true, accessToken, ...userData };
            } else {
                console.error('Login response missing token:', response.data);
                return { 
                    success: false, 
                    message: 'Неверный формат ответа от сервера' 
                };
            }
        } catch (error) {
            console.error('Login error:', error);
            return {
                success: false,
                message: error.response?.data?.message || 'Ошибка при входе в систему'
            };
        }
    },

    logout: async () => {
        localStorage.removeItem('authToken');
        localStorage.removeItem('userData');
        store.dispatch(logout());
    },

    validateToken,

    checkAuth: async () => {
        const token = localStorage.getItem('authToken');
        const userData = localStorage.getItem('userData');

        if (!token || !userData) {
            return false;
        }

        try {
            const isValid = await validateToken(token);
            if (!isValid) {
                localStorage.removeItem('authToken');
                localStorage.removeItem('userData');
                store.dispatch(logout());
                return false;
            }
            return true;
        } catch (error) {
            console.error('Auth check error:', error);
            localStorage.removeItem('authToken');
            localStorage.removeItem('userData');
            store.dispatch(logout());
            return false;
        }
    }
};

export { authApi }; 