import React, { useState, useEffect } from 'react';
import { Card, Table, Badge, Spinner, Alert, OverlayTrigger, Tooltip } from 'react-bootstrap';
import { useTheme } from '../ThemeProvider';
import { studyApi } from '../../api/studyApi';
import { useDispatch } from 'react-redux';
import { logout } from '../../store/slices/authSlice';
import { useNavigate } from 'react-router-dom';
import './StudyPlan.css';

const StudyPlan = () => {
    const [studyPlan, setStudyPlan] = useState(null);
    const [subjects, setSubjects] = useState([]);
    const [selectedTerm, setSelectedTerm] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const { isDark } = useTheme();
    const dispatch = useDispatch();
    const navigate = useNavigate();

    // Загружаем сам учебный план (год, количество семестров, текущий семестр)
    useEffect(() => {
        const fetchPlan = async () => {
            try {
                setLoading(true);
                setError(null);

                const planData = await studyApi.getStudyPlan();
                setStudyPlan(planData);
                // По умолчанию показываем текущий семестр
                if (planData.currentTerm) {
                    setSelectedTerm(planData.currentTerm);
                }
            } catch (err) {
                console.error('Error fetching study plan:', err);

                if (err.response?.status === 401) {
                    setError('Сессия истекла. Пожалуйста, войдите снова.');
                    dispatch(logout());
                } else {
                    setError(err.response?.data?.message || err.message || 'Ошибка при загрузке данных');
                }
            } finally {
                setLoading(false);
            }
        };

        fetchPlan();
    }, [dispatch]);

    // Подсчет фактического рейтинга по данным журнала предмета (как на странице предмета)
    const calculateFinalRatingFromJournal = (subjectData) => {
        if (!subjectData) return 0;

        const getAllControlPoints = (data) => {
            const currentControl = data.currentControl || [];
            const labs = data.labs || [];
            return [...currentControl, ...labs];
        };

        const allControlPoints = getAllControlPoints(subjectData);

        // Если нет ни одного элемента ни в текущем контроле/лабах, ни в аттестации — считаем,
        // что вообще нет данных и возвращаем null
        const hasAnyData =
            (allControlPoints && allControlPoints.length > 0) ||
            (subjectData.attestation && subjectData.attestation.length > 0);
        if (!hasAnyData) {
            return null;
        }

        // Текущий контроль (без бонусов)
        let currentWeighted = 0;
        let currentWeight = 0;
        allControlPoints.forEach((ctrl) => {
            const w = ctrl.weight || 1;
            const r = ctrl.rating || 0;
            currentWeighted += r * w;
            currentWeight += w;
        });
        const currentBase = currentWeight > 0 ? currentWeighted / currentWeight : 0;

        // Аттестация (если есть)
        let attAvg = 0;
        if (subjectData.attestation && subjectData.attestation.length > 0) {
            let attWeighted = 0;
            let attWeight = 0;
            subjectData.attestation.forEach((att) => {
                const w = att.weight || 1;
                const r = att.rating || 0;
                attWeighted += r * w;
                attWeight += w;
            });
            attAvg = attWeight > 0 ? attWeighted / attWeight : 0;
        }

        // Итог: если аттестация есть и не нулевая, применяем формулу 60/40
        const final =
            attAvg > 0
                ? currentBase * 0.6 + attAvg * 0.4
                : currentBase;

        return final;
    };

    // Загружаем предметы для выбранного семестра
    useEffect(() => {
        const fetchSubjects = async () => {
            if (!selectedTerm) return;
            try {
                setLoading(true);
                setError(null);

                const subjectsData = await studyApi.getSubjects(selectedTerm);
                const filteredSubjects = subjectsData
                    .filter(
                        subject =>
                            subject.termNumber === selectedTerm &&
                            subject.instructors &&
                            subject.instructors.length > 0
                    )
                    // Сортируем предметы: сначала экзамены, затем остальные
                    .sort((a, b) => {
                        if (a.controlType.toLowerCase() === 'экзамен' && b.controlType.toLowerCase() !== 'экзамен') {
                            return -1;
                        }
                        if (a.controlType.toLowerCase() !== 'экзамен' && b.controlType.toLowerCase() === 'экзамен') {
                            return 1;
                        }
                        return 0;
                    });

                // Для предметов, у которых rating <= 0, пробуем посчитать рейтинг по журналу,
                // используя ту же логику, что и на странице предмета
                const subjectsWithFixedRatings = await Promise.all(
                    filteredSubjects.map(async (subject) => {
                        if (subject.rating && subject.rating > 0) {
                            return subject;
                        }

                        try {
                            const isCourseWork = subject.controlType?.toLowerCase() === 'курсовые работы';
                            const journal = await studyApi.getSubjectJournal(
                                subject.disciplineId,
                                selectedTerm,
                                isCourseWork
                            );
                            const calculatedRating = calculateFinalRatingFromJournal(journal);

                            // Если по журналу вообще есть данные, но итоговый рейтинг может быть даже 0,
                            // считаем, что "данные есть" и показываем 0/любой другой факт вместо "Нет данных"
                            if (calculatedRating !== null && calculatedRating !== undefined) {
                                return {
                                    ...subject,
                                    rating: calculatedRating,
                                    hasJournalData: true,
                                };
                            }
                        } catch (e) {
                            console.error('Error fetching subject journal for discipline', subject.disciplineId, e);
                        }

                        // Если что-то пошло не так, возвращаем предмет как есть
                        return subject;
                    })
                );

                setSubjects(subjectsWithFixedRatings);
            } catch (err) {
                console.error('Error fetching subjects:', err);

                if (err.response?.status === 401) {
                    setError('Сессия истекла. Пожалуйста, войдите снова.');
                    dispatch(logout());
                } else {
                    setError(err.response?.data?.message || err.message || 'Ошибка при загрузке данных');
                }
            } finally {
                setLoading(false);
            }
        };

        fetchSubjects();
    }, [selectedTerm, dispatch]);

    const getRatingColor = (rating, controlType) => {
        const typeRaw = (controlType || '').toString().toLowerCase();
        
        // Для зачёта и дифференцированного зачёта
        if (typeRaw === 'зачет' || typeRaw === 'дифференцированный зачет') {
            return rating >= 59.01 ? 'success' : 'danger';
        }
        
        // Для экзамена и курсовых работ
        if (typeRaw === 'экзамен' || typeRaw === 'курсовые работы') {
            if (rating < 59.01) return 'danger';
            if (rating < 74.01) return 'warning text-dark';
            if (rating < 84.01) return 'primary';
            return 'success';
        }
        
        // Для остальных типов контроля
        return 'secondary';
    };

    const handleSubjectClick = (subjectId, controlType) => {
        // Открываем журнал предмета именно для выбранного семестра
        navigate(`/subject/${subjectId}/${selectedTerm}`, { state: { controlType } });
    };

    const getShortLastName = (lastName) => {
        if (lastName.length <= 4) return lastName;
        return lastName.slice(0, 3) + '.';
    };

    const renderInstructorName = (instructor) => {
        const fullName = `${instructor.lastName} ${instructor.firstName} ${instructor.middleName}`;
        
        return (
            <OverlayTrigger
                key={instructor.id}
                placement="top"
                overlay={<Tooltip>{fullName}</Tooltip>}
            >
                <span className="instructor-name">
                    {instructor.lastName}
                </span>
            </OverlayTrigger>
        );
    };

    const getControlTypeShort = (controlType) => {
        const type = controlType.toLowerCase();
        switch (type) {
            case 'экзамен':
                return 'Экз';
            case 'зачет':
                return 'Зач';
            case 'курсовые работы':
                return 'КР';
            case 'дифференцированный зачет':
                return 'ДЗ';
            default:
                return controlType;
        }
    };

    const renderControlType = (controlType) => {
        return (
            <OverlayTrigger
                placement="top"
                overlay={<Tooltip>{controlType}</Tooltip>}
            >
                <span className="control-type">
                    <span className="d-none d-sm-inline">{controlType}</span>
                    <span className="d-inline d-sm-none">{getControlTypeShort(controlType)}</span>
                </span>
            </OverlayTrigger>
        );
    };

    const renderContent = () => {
        if (loading) {
            return (
                <div className="study-plan-spinner">
                    <Spinner animation="border" variant={isDark ? 'light' : 'dark'} />
                </div>
            );
        }

        if (error) {
            return (
                <Alert variant="danger" className="study-plan-alert">
                    {error}
                </Alert>
            );
        }

        if (subjects.length === 0) {
            return (
                <Alert variant="info" className="study-plan-alert">
                    Нет предметов для текущего семестра
                </Alert>
            );
        }

        return (
            <div className="study-plan-table-wrap">
                <div className="study-plan-table">
                    <Table hover responsive className="study-table-modern">
                        <thead>
                            <tr>
                                <th className="discipline-col">Дисциплина</th>
                                <th className="instructor-col">
                                    <span className="d-none d-sm-inline">Преподаватели</span>
                                    <span className="d-inline d-sm-none">Преп.</span>
                                </th>
                                <th className="control-col">Тип</th>
                                <th className="rating-col">Рейтинг</th>
                            </tr>
                        </thead>
                        <tbody>
                            {subjects.map((subject) => (
                                <tr
                                    key={subject.disciplineId}
                                    onClick={() => handleSubjectClick(subject.disciplineId, subject.controlType)}
                                    className="hover-highlight"
                                >
                                    <td className="discipline-col">{subject.disciplineName}</td>
                                    <td className="instructor-col">
                                        <div className="instructors-list">
                                            {subject.instructors.map(renderInstructorName)}
                                        </div>
                                    </td>
                                    <td className="control-col">
                                        {renderControlType(subject.controlType)}
                                    </td>
                                    <td className="rating-col">
                                        {(subject.hasJournalData || subject.rating > 0) ? (
                                            <Badge bg={getRatingColor(subject.rating || 0, subject.controlType)}>
                                                {(subject.rating || 0).toFixed(2)}
                                            </Badge>
                                        ) : (
                                            <Badge bg="secondary">Нет данных</Badge>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </Table>
                </div>
            </div>
        );
    };

    return (
        <div className="page-wrapper study-plan-page">
            <Card className="study-plan-card card-modern">
                <Card.Header className="card-modern-header">
                    <div className="study-plan-header">
                        <div className="study-plan-title-block">
                            <h3 className="card-modern-title mb-1">Учебный план</h3>
                            {studyPlan && (
                                <p className="study-plan-subtitle">
                                    {studyPlan.year} · {studyPlan.termCount} семестров
                                </p>
                            )}
                        </div>
                        {studyPlan && (
                            <div className="study-plan-controls">
                                <div className="study-plan-term-info">
                                    <Badge bg="secondary" className="study-plan-term-badge">
                                        Семестр: {selectedTerm || studyPlan.currentTerm}
                                    </Badge>
                                </div>
                                <div className="study-plan-term-switch">
                                    <button
                                        type="button"
                                        className="term-switch-btn"
                                        disabled={!selectedTerm || selectedTerm <= 1}
                                        onClick={() => setSelectedTerm((prev) => Math.max(1, prev - 1))}
                                    >
                                        ←
                                    </button>
                                    <button
                                        type="button"
                                        className="term-switch-btn"
                                        disabled={
                                            !selectedTerm ||
                                            !studyPlan.termCount ||
                                            selectedTerm >= studyPlan.termCount
                                        }
                                        onClick={() =>
                                            setSelectedTerm((prev) =>
                                                Math.min(studyPlan.termCount, prev + 1)
                                            )
                                        }
                                    >
                                        →
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                </Card.Header>
                <Card.Body className="study-plan-body">
                    {renderContent()}
                </Card.Body>
            </Card>
        </div>
    );
};

export default StudyPlan; 