import axios from 'axios';

const BASE_URL = 'https://online.susu.ru/microgateway/api/StudyActivity';

// Ключи для локального кеша
const STORAGE_KEYS = {
    studyPlan: 'univeris-study-plan',
    subjects: (termNumber) => `univeris-subjects-${termNumber}`,
    subjectJournal: (subjectId, termNumber, isCourseWork) =>
        `univeris-subject-journal-${subjectId}-${termNumber}-${isCourseWork ? 'cw' : 'regular'}`,
    agreement: (subjectId) => `univeris-agreement-${subjectId}`,
};

// Создаем экземпляр axios с базовой конфигурацией
const api = axios.create({
    baseURL: BASE_URL,
});

// Добавляем перехватчик для добавления токена к каждому запросу
api.interceptors.request.use(
    (config) => {
        const token = localStorage.getItem('authToken');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

const studyApi = {
    // Пытаемся получить учебный план с сервера, иначе берем из localStorage
    getStudyPlan: async () => {
        try {
            const response = await api.get('/StudyPlan');
            const data = response.data;
            localStorage.setItem(STORAGE_KEYS.studyPlan, JSON.stringify(data));
            return data;
        } catch (error) {
            console.error('Error fetching study plan, trying cache:', error);
            const cached = localStorage.getItem(STORAGE_KEYS.studyPlan);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('Failed to parse cached study plan:', e);
                }
            }
            throw error;
        }
    },

    // Аналогично для списка предметов по семестру
    getSubjects: async (termNumber) => {
        const storageKey = STORAGE_KEYS.subjects(termNumber);
        try {
            const response = await api.get(`/Subjects/${termNumber}/ru`);
            const data = response.data;
            localStorage.setItem(storageKey, JSON.stringify(data));
            return data;
        } catch (error) {
            console.error('Error fetching subjects, trying cache:', error);
            const cached = localStorage.getItem(storageKey);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('Failed to parse cached subjects:', e);
                }
            }
            throw error;
        }
    },

    // Журнал по предмету: кешируем по комбинации subjectId/term/isCourseWork
    getSubjectJournal: async (subjectId, termNumber, isCourseWork = false) => {
        const storageKey = STORAGE_KEYS.subjectJournal(subjectId, termNumber, isCourseWork);
        try {
            const response = await api.get(
                `/Journal/${subjectId}/${termNumber}/IsCourseWorkOrProject/${isCourseWork}/ru`
            );
            const data = response.data;
            localStorage.setItem(storageKey, JSON.stringify(data));
            return data;
        } catch (error) {
            console.error('Error fetching subject journal, trying cache:', error);
            const cached = localStorage.getItem(storageKey);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('Failed to parse cached subject journal:', e);
                }
            }
            throw error;
        }
    },

    // Статус согласия: при ошибке используем локальное значение
    checkAgreementStatus: async (subjectId) => {
        const storageKey = STORAGE_KEYS.agreement(subjectId);
        try {
            const response = await api.get(`/IsAllowSetAgreement/${subjectId}`);
            const data = response.data;
            localStorage.setItem(storageKey, JSON.stringify(data));
            return data;
        } catch (error) {
            console.error('Error checking agreement status, trying cache:', error);
            const cached = localStorage.getItem(storageKey);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('Failed to parse cached agreement status:', e);
                }
            }
            throw error;
        }
    },

    // Устанавливаем согласие: даже если сеть недоступна, сохраняем локально
    setAgreement: async (subjectId, isAgreed) => {
        const storageKey = STORAGE_KEYS.agreement(subjectId);
        try {
            const response = await api.post(`/SetMarkAgreement/${subjectId}/${isAgreed}`);
            const data = response.data;
            // Сохраняем последнее известное состояние согласия
            localStorage.setItem(
                storageKey,
                JSON.stringify({
                    ...(typeof data === 'object' && data !== null ? data : {}),
                    isAgreed,
                })
            );
            return data;
        } catch (error) {
            console.error('Error setting agreement, saving locally only:', error);
            // Офлайн-режим: сохраняем только локально
            const localData = { isAgreed, offlineOnly: true };
            localStorage.setItem(storageKey, JSON.stringify(localData));
            return localData;
        }
    },
};

export { studyApi };